/**
 * GeoSafe - Lightweight Self-Contained Offline QR Code Generator
 * Pure JavaScript, Zero Dependencies, Zero External Network Calls.
 * Supports Byte Mode, Error Correction L/M, up to 120 alphanumeric chars.
 */
(function(root, factory) {
  if (typeof define === 'function' && define.amd) {
    define([], factory);
  } else if (typeof module === 'object' && module.exports) {
    module.exports = factory();
  } else {
    root.QRCode = factory();
  }
}(typeof self !== 'undefined' ? self : this, function() {
  'use strict';

  // Galois Field GF(256) Tables for Reed-Solomon Error Correction
  const EXP_TABLE = new Array(256);
  const LOG_TABLE = new Array(256);
  for (let i = 0, x = 1; i < 256; i++) {
    EXP_TABLE[i] = x;
    LOG_TABLE[x] = i;
    x = (x << 1) ^ (x >= 128 ? 0x11d : 0);
  }

  function gfMul(x, y) {
    if (x === 0 || y === 0) return 0;
    return EXP_TABLE[(LOG_TABLE[x] + LOG_TABLE[y]) % 255];
  }

  function rsPolyGen(errorCount) {
    let poly = [1];
    for (let i = 0; i < errorCount; i++) {
      const factor = [1, EXP_TABLE[i]];
      const newPoly = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        newPoly[j] ^= poly[j];
        newPoly[j + 1] ^= gfMul(poly[j], factor[1]);
      }
      poly = newPoly;
    }
    return poly;
  }

  function rsEncode(data, errorCount) {
    const gen = rsPolyGen(errorCount);
    const result = new Array(data.length + errorCount).fill(0);
    for (let i = 0; i < data.length; i++) {
      result[i] = data[i];
    }
    for (let i = 0; i < data.length; i++) {
      const coef = result[i];
      if (coef !== 0) {
        for (let j = 0; j < gen.length; j++) {
          result[i + j] ^= gfMul(gen[j], coef);
        }
      }
    }
    for (let i = 0; i < data.length; i++) {
      result[i] = data[i];
    }
    return result.slice(data.length);
  }

  // QR Specs for Version 1..6 (Byte mode, Error Correction Level M)
  const VERSION_SPECS = [
    null,
    { version: 1, size: 21, totalDataBytes: 16, ecBytes: 10, align: [] },
    { version: 2, size: 25, totalDataBytes: 28, ecBytes: 16, align: [6, 18] },
    { version: 3, size: 29, totalDataBytes: 44, ecBytes: 26, align: [6, 22] },
    { version: 4, size: 33, totalDataBytes: 64, ecBytes: 18 * 2, align: [6, 26], blocks: 2 },
    { version: 5, size: 37, totalDataBytes: 86, ecBytes: 24 * 2, align: [6, 30], blocks: 2 },
    { version: 6, size: 41, totalDataBytes: 108, ecBytes: 28 * 2, align: [6, 34], blocks: 4 }
  ];

  function getBestVersion(dataLength) {
    for (let v = 1; v <= 6; v++) {
      const spec = VERSION_SPECS[v];
      // 4-bit mode indicator + 8-bit length indicator
      const maxPayload = spec.totalDataBytes - 2;
      if (dataLength <= maxPayload) return spec;
    }
    return VERSION_SPECS[6];
  }

  class QRMatrix {
    constructor(spec) {
      this.spec = spec;
      this.size = spec.size;
      this.modules = Array.from({ length: this.size }, () => new Array(this.size).fill(null));
      this.reserved = Array.from({ length: this.size }, () => new Array(this.size).fill(false));
      this.initPatterns();
    }

    set(r, c, val, isReserved = false) {
      this.modules[r][c] = val ? 1 : 0;
      if (isReserved) this.reserved[r][c] = true;
    }

    initPatterns() {
      // Finder patterns (top-left, top-right, bottom-left)
      this.addFinder(0, 0);
      this.addFinder(0, this.size - 7);
      this.addFinder(this.size - 7, 0);

      // Separators
      for (let i = 0; i < 8; i++) {
        this.setRes(7, i, 0);
        this.setRes(i, 7, 0);
        this.setRes(7, this.size - 1 - i, 0);
        this.setRes(i, this.size - 8, 0);
        this.setRes(this.size - 8, i, 0);
        this.setRes(this.size - 1 - i, 7, 0);
      }

      // Timing patterns
      for (let i = 8; i < this.size - 8; i++) {
        this.setRes(6, i, i % 2 === 0 ? 1 : 0);
        this.setRes(i, 6, i % 2 === 0 ? 1 : 0);
      }

      // Alignment patterns
      if (this.spec.align && this.spec.align.length > 0) {
        const coords = this.spec.align;
        for (let r = 0; r < coords.length; r++) {
          for (let c = 0; c < coords.length; c++) {
            const row = coords[r];
            const col = coords[c];
            if (this.reserved[row][col]) continue;
            this.addAlignment(row, col);
          }
        }
      }

      // Reserve format info areas
      for (let i = 0; i < 9; i++) {
        this.setRes(8, i, 0);
        this.setRes(i, 8, 0);
      }
      for (let i = 0; i < 8; i++) {
        this.setRes(8, this.size - 1 - i, 0);
        this.setRes(this.size - 1 - i, 8, 0);
      }
      this.setRes(this.size - 8, 8, 1); // Dark module
    }

    setRes(r, c, val) {
      if (r >= 0 && r < this.size && c >= 0 && c < this.size) {
        this.modules[r][c] = val;
        this.reserved[r][c] = true;
      }
    }

    addFinder(row, col) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const rr = row + r;
          const cc = col + c;
          if (rr >= 0 && rr < this.size && cc >= 0 && cc < this.size) {
            const isBlack = (r >= 0 && r <= 6 && (c === 0 || c === 6)) ||
                            (c >= 0 && c <= 6 && (r === 0 || r === 6)) ||
                            (r >= 2 && r <= 4 && c >= 2 && c <= 4);
            this.setRes(rr, cc, isBlack ? 1 : 0);
          }
        }
      }
    }

    addAlignment(row, col) {
      for (let r = -2; r <= 2; r++) {
        for (let c = -2; c <= 2; c++) {
          const isBlack = Math.abs(r) === 2 || Math.abs(c) === 2 || (r === 0 && c === 0);
          this.setRes(row + r, col + c, isBlack ? 1 : 0);
        }
      }
    }

    applyFormatInfo(maskPattern) {
      // Format info bits for Level M, mask 0..7
      // Precomputed format info integers with BCH code & mask 0x5412
      const FORMAT_BITS = [
        0x4ad4, 0x4fa3, 0x40c6, 0x45b1, 0x529e, 0x57e9, 0x588c, 0x5dfb
      ];
      const bits = FORMAT_BITS[maskPattern % 8];
      for (let i = 0; i < 15; i++) {
        const bit = (bits >> i) & 1;
        // Top-left
        if (i <= 5) this.modules[8][i] = bit;
        else if (i === 6) this.modules[8][7] = bit;
        else if (i === 7) this.modules[8][8] = bit;
        else if (i === 8) this.modules[7][8] = bit;
        else this.modules[14 - i][8] = bit;

        // Top-right and bottom-left
        if (i < 8) this.modules[this.size - 1 - i][8] = bit;
        else this.modules[8][this.size - 15 + i] = bit;
      }
    }

    fillData(codewords, mask = 0) {
      let bitIdx = 0;
      const totalBits = codewords.length * 8;
      let upward = true;

      for (let right = this.size - 1; right > 0; right -= 2) {
        if (right === 6) right--; // Skip vertical timing column
        const cols = [right, right - 1];

        const rowRange = upward
          ? Array.from({ length: this.size }, (_, i) => this.size - 1 - i)
          : Array.from({ length: this.size }, (_, i) => i);

        for (const row of rowRange) {
          for (const col of cols) {
            if (!this.reserved[row][col]) {
              let bit = 0;
              if (bitIdx < totalBits) {
                const byte = codewords[Math.floor(bitIdx / 8)];
                bit = (byte >> (7 - (bitIdx % 8))) & 1;
                bitIdx++;
              }
              // Mask condition (Pattern 0: (row + col) % 2 === 0)
              const maskBit = ((row + col) % 2 === 0) ? 1 : 0;
              this.modules[row][col] = bit ^ maskBit;
            }
          }
        }
        upward = !upward;
      }
      this.applyFormatInfo(0);
    }
  }

  function encodeDataToCodewords(text, spec) {
    const utf8Bytes = [];
    for (let i = 0; i < text.length; i++) {
      let code = text.charCodeAt(i);
      if (code < 0x80) utf8Bytes.push(code);
      else if (code < 0x800) {
        utf8Bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
      } else {
        utf8Bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
      }
    }

    // Byte mode header: Mode indicator 0100 (4 bits) + character count (8 bits)
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) {
        bits.push((val >> i) & 1);
      }
    }

    pushBits(0b0100, 4); // Byte mode
    pushBits(utf8Bytes.length, 8); // Character count
    for (const b of utf8Bytes) {
      pushBits(b, 8);
    }

    // Terminator (up to 4 zeroes)
    const totalDataBits = spec.totalDataBytes * 8;
    const termLen = Math.min(4, totalDataBits - bits.length);
    for (let i = 0; i < termLen; i++) bits.push(0);

    // Byte align
    while (bits.length % 8 !== 0) bits.push(0);

    // Convert bits to data bytes
    const dataBytes = [];
    for (let i = 0; i < bits.length; i += 8) {
      let byte = 0;
      for (let j = 0; j < 8; j++) byte = (byte << 1) | bits[i + j];
      dataBytes.push(byte);
    }

    // Pad bytes 0xEC, 0x11
    const padBytes = [0xEC, 0x11];
    let padIdx = 0;
    while (dataBytes.length < spec.totalDataBytes) {
      dataBytes.push(padBytes[padIdx % 2]);
      padIdx++;
    }

    // Compute error correction codewords
    const ecPerBlock = spec.ecBytes / (spec.blocks || 1);
    const dataPerBlock = dataBytes.length / (spec.blocks || 1);

    const dataBlocks = [];
    const ecBlocks = [];

    for (let b = 0; b < (spec.blocks || 1); b++) {
      const blockData = dataBytes.slice(b * dataPerBlock, (b + 1) * dataPerBlock);
      dataBlocks.push(blockData);
      ecBlocks.push(rsEncode(blockData, ecPerBlock));
    }

    // Interleave data blocks and then ec blocks
    const finalCodewords = [];
    for (let i = 0; i < dataPerBlock; i++) {
      for (let b = 0; b < dataBlocks.length; b++) {
        finalCodewords.push(dataBlocks[b][i]);
      }
    }
    for (let i = 0; i < ecPerBlock; i++) {
      for (let b = 0; b < ecBlocks.length; b++) {
        finalCodewords.push(ecBlocks[b][i]);
      }
    }

    return finalCodewords;
  }

  function generateMatrix(text) {
    const spec = getBestVersion(text.length);
    const codewords = encodeDataToCodewords(text, spec);
    const matrix = new QRMatrix(spec);
    matrix.fillData(codewords, 0);
    return matrix;
  }

  return {
    toSVG(text, options = {}) {
      const matrix = generateMatrix(text);
      const size = options.size || 220;
      const margin = options.margin !== undefined ? options.margin : 4;
      const modCount = matrix.size + margin * 2;
      const modSize = size / modCount;

      let rects = '';
      for (let r = 0; r < matrix.size; r++) {
        for (let c = 0; c < matrix.size; c++) {
          if (matrix.modules[r][c] === 1) {
            const x = ((c + margin) * modSize).toFixed(2);
            const y = ((r + margin) * modSize).toFixed(2);
            const w = (modSize + 0.05).toFixed(2);
            const h = (modSize + 0.05).toFixed(2);
            rects += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#202020" rx="1"/>`;
          }
        }
      }

      return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" class="mx-auto select-none">
        <rect width="100%" height="100%" fill="#FFFFFF" rx="16"/>
        ${rects}
      </svg>`;
    },

    renderTo(element, text, options = {}) {
      if (typeof element === 'string') {
        element = document.getElementById(element);
      }
      if (!element) return;
      element.innerHTML = this.toSVG(text, options);
    }
  };
}));

